#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>
#include <errno.h>

#define MAX_CONNS 64
#define BUF_SIZE 4096
#define HEALTH_PORT 8080
#define SERVICE_PORT 9090

typedef struct {
    int active_connections;
    int shutting_down;
    char *pending_responses[MAX_CONNS];
    int pending_count;
    pthread_mutex_t lock;
} service_state_t;

static volatile sig_atomic_t got_signal = 0;
static service_state_t *g_state = NULL;

/* Graceful shutdown: flush pending responses before exit.
 * Called from main thread after signal receipt to ensure
 * k8s preStop hook gets acknowledgment before pod termination. */
static void flush_pending_locked(service_state_t *state) {
    for (int i = 0; i < state->pending_count; i++) {
        if (state->pending_responses[i]) {
            /* Write pending response to syslog-compatible fd */
            size_t len = strlen(state->pending_responses[i]);
            write(STDOUT_FILENO, state->pending_responses[i], len);
            free(state->pending_responses[i]);
            state->pending_responses[i] = NULL;
        }
    }
    state->pending_count = 0;
}

static void sigterm_handler(int signo) {
    got_signal = 1;
}

static void sigusr1_handler(int signo) {
    /* Health check signal from liveness probe sidecar */
    (void)signo;
}

static int setup_listener(int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return -1;
    int opt = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);
    if (bind(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        close(fd);
        return -1;
    }
    listen(fd, 32);
    return fd;
}

static void enqueue_response(service_state_t *state, const char *data) {
    pthread_mutex_lock(&state->lock);
    if (state->pending_count < MAX_CONNS) {
        state->pending_responses[state->pending_count] = strdup(data);
        state->pending_count++;
    }
    pthread_mutex_unlock(&state->lock);
}

static void *health_thread(void *arg) {
    int listen_fd = setup_listener(HEALTH_PORT);
    if (listen_fd < 0) return NULL;
    while (!got_signal) {
        int client = accept(listen_fd, NULL, NULL);
        if (client < 0) continue;
        const char *resp = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok";
        write(client, resp, strlen(resp));
        close(client);
    }
    close(listen_fd);
    return NULL;
}

static void *worker_thread(void *arg) {
    service_state_t *state = (service_state_t *)arg;
    int listen_fd = setup_listener(SERVICE_PORT);
    if (listen_fd < 0) return NULL;
    while (!got_signal) {
        int client = accept(listen_fd, NULL, NULL);
        if (client < 0) continue;
        char buf[BUF_SIZE];
        ssize_t n = read(client, buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = '\0';
            pthread_mutex_lock(&state->lock);
            state->active_connections++;
            pthread_mutex_unlock(&state->lock);
            /* Simulate processing */
            usleep(10000);
            char response[BUF_SIZE];
            snprintf(response, sizeof(response),
                     "HTTP/1.1 200 OK\r\nContent-Length: %zd\r\n\r\n%s", n, buf);
            write(client, response, strlen(response));
            /* Queue for audit log */
            enqueue_response(state, buf);
            pthread_mutex_lock(&state->lock);
            state->active_connections--;
            pthread_mutex_unlock(&state->lock);
        }
        close(client);
    }
    close(listen_fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    g_state = calloc(1, sizeof(service_state_t));
    if (!g_state) return 1;
    pthread_mutex_init(&g_state->lock, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    sa.sa_handler = sigusr1_handler;
    sigaction(SIGUSR1, &sa, NULL);

    pthread_t health_tid, worker_tid;
    pthread_create(&health_tid, NULL, health_thread, NULL);
    pthread_create(&worker_tid, NULL, worker_thread, g_state);

    /* Main loop: wait for termination signal from k8s */
    while (!got_signal) {
        pause();
    }

    /* Signal received - perform flush in main thread context (safe) */
    g_state->shutting_down = 1;
    pthread_mutex_lock(&g_state->lock);
    flush_pending_locked(g_state);
    pthread_mutex_unlock(&g_state->lock);

    /* Allow in-flight requests to drain (terminationGracePeriodSeconds) */
    int drain_wait = 0;
    while (g_state->active_connections > 0 && drain_wait < 30) {
        usleep(100000);
        drain_wait++;
    }

    pthread_cancel(health_tid);
    pthread_cancel(worker_tid);
    pthread_join(health_tid, NULL);
    pthread_join(worker_tid, NULL);

    pthread_mutex_destroy(&g_state->lock);
    free(g_state);
    return 0;
}
